"""Get index of TM helix given a residue position
    Return -1 if iRes is not within TM region
    """
def GetTMIndex(iRes: Any, posTM: Any) -> object {
    for i in range(len(posTM)) {
        (b, e) = posTM[i];
        if ((iRes >= b) and (iRes < e)) {
            return i;
        }
    }
    return -1;
}

